def handle(inbound_token, document_id):
    claims = verifier.verify(inbound_token, issuer=TRUSTED_ISSUER, check_expiry=True, check_audience=False)
    require_scope(claims, 'documents:read')
    return upstream.get_document(document_id, bearer=inbound_token)

def handle(inbound_token, document_id):
    actor = verifier.verify(inbound_token, issuer=TRUSTED_ISSUER, audience=MCP_RESOURCE, check_expiry=True)
    require_scope(actor, 'documents:read')
    require_owned_document(actor, document_id)
    upstream_token = credential_broker.for_resource(actor.id, UPSTREAM_RESOURCE)
    return upstream.get_document(document_id, bearer=upstream_token)

