def consume(result, private_document):
    for call in planner(result, private_document):
        tools[call.name](**call.arguments)

def consume(result, private_document, grant):
    for call in planner(result, private_document):
        if not policy.allows(grant, call.name, call.arguments):
            continue
        tools[call.name](**call.arguments)

