def delete_document(session, document_id):
    actor = authenticate(session)
    require_owned_document(actor, document_id)
    return documents.delete(document_id)

def delete_document(session, document_id, approval):
    actor = authenticate(session)
    require_owned_document(actor, document_id)
    with transaction():
        approvals.consume(approval, actor.id, document_id, action='delete')
        return documents.delete(document_id)
